package scheduler

import (
	"hash/fnv"
	"sync"
	"time"
)

// PiDigits 存储圆周率 π 小数点后前 2000 位纯数字。
const PiDigits = ""

// PiSchedule 基于 π 混沌序列的单账号游标调度器。
type PiSchedule struct {
	mu     sync.Mutex
	cursor int
	step   int
}

// UIDHash 使用 FNV-1a 算法计算 UID 哈希。
func UIDHash(uid string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(uid))
	return h.Sum32()
}

// CalculateStep 基于哈希值计算与 2000 互质的步长。
// 2000 = 2^4 * 5^3，因此只要 step 既非偶数又非 5 的倍数，就与 2000 互质（gcd(step, 2000) == 1）。
func CalculateStep(h uint32) int {
	step := int((h%999)*2 + 1)
	if step%5 == 0 {
		step += 2
	}
	return step
}

// GCD 计算两个整数的最大公约数。
func GCD(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

// NewPiSchedule 为指定 uid 初始化基于 π 混沌序列的调度器。
func NewPiSchedule(uid string) *PiSchedule {
	h := UIDHash(uid)
	cursor := int(h % uint32(len(PiDigits)))
	step := CalculateStep(h)
	return &PiSchedule{
		cursor: cursor,
		step:   step,
	}
}

// InitialDelay 计算冷启动打散时间：打散在 [5s, 300s] 内，杜绝服务启动瞬发并发。
func (p *PiSchedule) InitialDelay() time.Duration {
	p.mu.Lock()
	defer p.mu.Unlock()
	num := p.peekNumberLocked()
	// [5s, 300s] 区间跨度 296 秒 (5s ~ 300s)
	sec := 5 + (num % 296)
	return time.Duration(sec) * time.Second
}

// NextDelay 取连续 3 位数字（000~999），映射到 [300s, 600s]（5分~10分，即 300*time.Second + time.Duration(num % 301)*time.Second）。
func (p *PiSchedule) NextDelay() time.Duration {
	p.mu.Lock()
	defer p.mu.Unlock()
	num := p.nextNumberLocked()
	return 300*time.Second + time.Duration(num%301)*time.Second
}

// NextDelayForInterval 支持配置热改扩展：当全局基础间隔不为默认 5 分钟且 > 0 时按比例缩放，若等于 5 分钟则完全等同于 NextDelay。
func (p *PiSchedule) NextDelayForInterval(base time.Duration) time.Duration {
	if base <= 0 {
		return 0
	}
	if base == 5*time.Minute {
		return p.NextDelay()
	}
	p.mu.Lock()
	defer p.mu.Unlock()
	num := p.nextNumberLocked()
	jitter := time.Duration(float64(base) * float64(num%301) / 300.0)
	return base + jitter
}

// Cursor 返回当前游标位置（测试观测用）。
func (p *PiSchedule) Cursor() int {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.cursor
}

// Step 返回当前步长。
func (p *PiSchedule) Step() int {
	return p.step
}

func (p *PiSchedule) peekNumberLocked() int {
	n := len(PiDigits)
	d1 := int(PiDigits[p.cursor] - '0')
	d2 := int(PiDigits[(p.cursor+1)%n] - '0')
	d3 := int(PiDigits[(p.cursor+2)%n] - '0')
	return d1*100 + d2*10 + d3
}

func (p *PiSchedule) nextNumberLocked() int {
	num := p.peekNumberLocked()
	p.cursor = (p.cursor + p.step) % len(PiDigits)
	return num
}
